const loginData = $("1. Login to ByteWire API").first().json;
const token = loginData.token;
const allItems = $input.all().map(item => item.json);
const videoList = allItems.length === 1 && Array.isArray(allItems[0]) ? allItems[0] : allItems;
let targetVideoId = null;
let singleShortIndex = null;
let isSingleShort = false;
let webhookPayload = null;
try {
  const webhookNode = $("Webhook Trigger (ByteWire Push)").first();
  webhookPayload = webhookNode?.json?.body || webhookNode?.json;
  targetVideoId = webhookPayload?.videoId;
  singleShortIndex = webhookPayload?.shortIndex || webhookPayload?.factIndex;
  isSingleShort = webhookPayload?.action === "post_reel" || webhookPayload?.event === "upload_single_short" || !!singleShortIndex;
} catch (_) {}
let pendingUploads = [];
if (isSingleShort && targetVideoId) {
  pendingUploads = videoList.filter(v => v && String(v._id) === String(targetVideoId));
} else if (targetVideoId) {
  pendingUploads = videoList.filter(v => v && String(v._id) === String(targetVideoId) && !v.youtubeVideoId);
}
if (pendingUploads.length === 0 && !isSingleShort) {
  pendingUploads = videoList.filter(v => v && v.status === "Completed" && !v.youtubeVideoId);
}
if (pendingUploads.length === 0) { return [{ json: { skip: true, message: "No new completed videos to upload." } }]; }
const video = pendingUploads[0];
return [{ json: { skip: false, isSingleShort: isSingleShort, singleShortIndex: singleShortIndex, webhookPayload: webhookPayload, videoId: video._id, token: token, title: video.title, subject: video.subject, status: video.status, youtubeMetadata: video.youtubeMetadata || {}, shorts: video.shorts || [], shortsCount: (video.shorts || []).length, videoUrl: "https://ytvideo.harikothapalli.space/videos/" + video._id + ".mp4", thumbnailUrl: "https://ytvideo.harikothapalli.space/thumbnails/" + video._id + ".png" } }];

const video = $input.first().json;
const findPending = $("3. Find Pending Upload").first().json;
const isSingleShort = findPending.isSingleShort;
const singleShortIndex = Number(findPending.singleShortIndex) || 1;
const webhookPayload = findPending.webhookPayload || {};
const token = findPending.token;

if (isSingleShort) {
  const shorts = video.shorts || [];
  const short = shorts.find((s, idx) => Number(s.factIndex) === singleShortIndex || (idx + 1) === singleShortIndex) || shorts[0] || {};
  const ytMeta = short.youtubeMetadata || {};
  const factTitle = short.factTitle || short.title || ("News Short #" + singleShortIndex);
  const rawTitle = webhookPayload.title || ytMeta.title || (factTitle + " #Shorts");
  const finalTitle = (rawTitle.includes("#Shorts") || rawTitle.includes("#shorts")) ? rawTitle : (rawTitle.substring(0, 90) + " #Shorts");
  const parentLink = video.youtubeUrl ? ("\n\nFull Video: " + video.youtubeUrl) : "";
  const shortDesc = webhookPayload.description || (ytMeta.description || (short.scriptText || factTitle) + parentLink + "\n\n#shorts #youtubeshorts #news #trending #bytewire");
  const shortTags = webhookPayload.tags || (ytMeta.tags || ["shorts", "news", "trending", "youtubeshorts", "bytewire"]);
  const videoDownloadUrl = "https://ytvideo.harikothapalli.space/api/download/" + video._id + "/short/" + singleShortIndex;

  return [{ json: { isSingleShort: true, videoId: video._id, shortIndex: singleShortIndex, token: token, title: finalTitle.substring(0, 100), description: shortDesc.substring(0, 5000), tags: shortTags.slice(0, 15).map(t => String(t).trim()).filter(Boolean), categoryId: "25", privacyStatus: "public", madeForKids: false, videoDownloadUrl: videoDownloadUrl, shorts: [], shortsCount: 0 } }];
}

const meta = video.youtubeMetadata || {};
const title = (meta.title || video.title || "ByteWire AI News").substring(0, 100);
const description = (meta.description || "Top 10 " + video.subject + " news. Subscribe to ByteWire! #news #trending").substring(0, 5000);
const tags = (meta.tags || ["news", "trending", "bytewire"]).slice(0, 15).map(t => String(t).trim()).filter(Boolean);
const videoDownloadUrl = "https://ytvideo.harikothapalli.space/api/download/" + video._id;
return [{ json: { isSingleShort: false, videoId: video._id, title: title, description: description, tags: tags, categoryId: "25", privacyStatus: "public", madeForKids: false, videoDownloadUrl: videoDownloadUrl, thumbnailUrl: "https://ytvideo.harikothapalli.space/thumbnails/" + video._id + ".png", shorts: video.shorts || [], shortsCount: (video.shorts || []).length, token: token } }];

const ytResult = $input.first().json;
const youtubeVideoId = ytResult.uploadId || ytResult.id || "";
const preparedData = $("6. Prepare Full Video Data").first().json;

if (preparedData.isSingleShort) {
  if (youtubeVideoId && preparedData.videoId && preparedData.token) {
    try {
      await fetch("https://ytvideo.harikothapalli.space/api/video/" + preparedData.videoId + "/short/" + preparedData.shortIndex + "/youtube", {
        method: "PATCH",
        headers: { "Content-Type": "application/json", "Authorization": "Bearer " + preparedData.token },
        body: JSON.stringify({ youtubeShortId: youtubeVideoId, youtubeShortUrl: "https://www.youtube.com/shorts/" + youtubeVideoId })
      });
    } catch (_) {}
  }
  return [{ json: { skipShorts: true, isSingleShort: true, youtubeShortId: youtubeVideoId, youtubeShortUrl: "https://www.youtube.com/shorts/" + youtubeVideoId, message: "Reel #" + preparedData.shortIndex + " successfully published to YouTube!" } }];
}

const shorts = preparedData.shorts || [];
if (youtubeVideoId && preparedData.videoId && preparedData.token) {
  try {
    await fetch("https://ytvideo.harikothapalli.space/api/video/" + preparedData.videoId + "/youtube", {
      method: "PATCH",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + preparedData.token },
      body: JSON.stringify({ youtubeVideoId: youtubeVideoId })
    });
  } catch (_) {}
}
if (shorts.length === 0) {
  return [{ json: { skipShorts: true, message: "Full video uploaded to YouTube: " + youtubeVideoId + ". No shorts found on this older video.", parentYoutubeId: youtubeVideoId, parentYoutubeUrl: "https://www.youtube.com/watch?v=" + youtubeVideoId } }];
}
const shortsWithContext = shorts.map((s, idx) => ({
  ...s,
  skipShorts: false,
  parentVideoId: preparedData.videoId,
  parentYoutubeId: youtubeVideoId,
  parentYoutubeUrl: "https://www.youtube.com/watch?v=" + youtubeVideoId,
  shortDownloadUrl: "https://ytvideo.harikothapalli.space/api/download/" + preparedData.videoId + "/short/" + (s.factIndex || (idx + 1)),
  token: preparedData.token
}));
return shortsWithContext.map(s => ({ json: s }));

const shortData = $("10. Split Shorts (1 at a time)").first().json;
const ytMeta = shortData.youtubeMetadata || {};
const factTitle = shortData.factTitle || shortData.title || ("News Short #" + (shortData.factIndex || 1));
const rawShortTitle = ytMeta.title || (factTitle.substring(0, 50) + " #Shorts");
const finalTitle = (rawShortTitle.includes("#Shorts") || rawShortTitle.includes("#shorts")) ? rawShortTitle : (rawShortTitle.substring(0, 52) + " #Shorts");
const parentLink = shortData.parentYoutubeUrl ? "\n\nFull Video: " + shortData.parentYoutubeUrl : "";
const shortDesc = (ytMeta.description || (shortData.scriptText || factTitle) + parentLink + "\n\n#shorts #youtubeshorts #news #trending #bytewire").substring(0, 5000);
const shortTags = (ytMeta.tags || ["shorts", "news", "trending", "youtubeshorts", "bytewire"]).slice(0, 15).map(t => String(t).trim()).filter(Boolean);

// Calculate 4 Shorts per day staggered publishing schedule (09:00, 13:00, 17:00, 21:00 IST)
const factIdx = Number(shortData.factIndex) || 1;
const slotHoursIST = [9, 13, 17, 21];
const dayOffset = Math.floor((factIdx - 1) / 4);
const slotIdx = (factIdx - 1) % 4;
const targetHourIST = slotHoursIST[slotIdx];

const scheduledDate = new Date();
scheduledDate.setDate(scheduledDate.getDate() + 1 + dayOffset);
const targetUTCMinutes = (targetHourIST * 60) - 330;
scheduledDate.setUTCHours(Math.floor(targetUTCMinutes / 60), targetUTCMinutes % 60, 0, 0);

return [{ json: { ...shortData, uploadTitle: finalTitle.substring(0, 100), uploadDescription: shortDesc, uploadTags: shortTags, scheduledPublishAt: scheduledDate.toISOString(), scheduleSlot: targetHourIST + ":00 IST (Day " + (dayOffset + 1) + ")" } }];

const uploadResult = $input.first().json;
const shortData = $("12. Prepare Short Metadata").first().json;
const ytShortId = uploadResult.id;
return [{ json: { factIndex: shortData.factIndex, title: shortData.uploadTitle, youtubeShortId: ytShortId, youtubeShortUrl: "https://www.youtube.com/shorts/" + ytShortId, parentVideoId: shortData.parentVideoId, parentYoutubeId: shortData.parentYoutubeId } }];

const allResults = $input.all().map(r => r.json);
const first = allResults[0] || {};
if (first.isSingleShort) {
  return [{ json: { status: "success", timestamp: new Date().toISOString(), youtubeShortId: first.youtubeShortId, youtubeShortUrl: first.youtubeShortUrl, message: first.message || "Reel published to YouTube successfully!" } }];
}
const allShortResults = allResults.filter(r => r && r.factIndex);
const summary = { status: "success", timestamp: new Date().toISOString(), parentYoutubeId: first?.parentYoutubeId || "N/A", parentYoutubeUrl: first?.parentYoutubeId ? "https://www.youtube.com/watch?v=" + first.parentYoutubeId : "N/A", shortsUploaded: allShortResults.map(r => ({ factIndex: r.factIndex, title: r.title, url: r.youtubeShortUrl })), totalShortsUploaded: allShortResults.length, message: "ByteWire Upload Complete: 1 full video + " + allShortResults.length + " Shorts published to YouTube!" };
return [{ json: summary }];
